// HasShipment applies the HasEdge predicate on the "shipment" edge.
func HasShipment() predicate.ChainOfCustody {
	return predicate.ChainOfCustody(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ShipmentTable, ShipmentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasShipmentWith applies the HasEdge predicate on the "shipment" edge with a given conditions (other predicates).
func HasShipmentWith(preds ...predicate.Shipment) predicate.ChainOfCustody {
	return predicate.ChainOfCustody(func(s *sql.Selector) {
		step := newShipmentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChainOfCustody) predicate.ChainOfCustody {
	return predicate.ChainOfCustody(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChainOfCustody) predicate.ChainOfCustody {
	return predicate.ChainOfCustody(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChainOfCustody) predicate.ChainOfCustody {
	return predicate.ChainOfCustody(sql.NotPredicates(p))
}
